import { isValidDueDate } from '/date-validation.js';

const app = document.querySelector('#app');

function element(tag, text) {
  const node = document.createElement(tag);
  if (text !== undefined) node.textContent = text;
  return node;
}

function showError(message) {
  let alert = app.querySelector('[role="alert"]');
  if (!alert) {
    alert = element('p');
    alert.setAttribute('role', 'alert');
    app.append(alert);
  }
  alert.textContent = message;
}

async function request(path, options) {
  const response = await fetch(path, options);
  const body = await response.json();
  if (!response.ok) throw new Error(body.error || 'Request failed');
  return body;
}

// Fold only ASCII letters; non-ASCII characters and internal whitespace stay exact.
function searchMatches(text, query) {
  const fold = value => value.replace(/[A-Z]/g, letter => letter.toLowerCase());
  return fold(text).includes(fold(query));
}

function searchForm(kind, onSearch) {
  const form = element('form');
  const label = element('label', `${kind} search`);
  const input = element('input');
  input.id = `${kind.toLowerCase()}-search`;
  input.type = 'text';
  label.htmlFor = input.id;
  const submit = element('button', kind === 'Project' ? 'Search projects' : 'Search tasks');
  submit.type = 'submit';
  form.append(label, input, submit);
  form.addEventListener('submit', event => {
    event.preventDefault();
    const query = input.value.trim();
    input.value = query;
    onSearch(query);
  });
  return form;
}

function projectsButton() {
  const button = element('button', 'Projects');
  button.type = 'button';
  button.addEventListener('click', () => location.assign('/'));
  return button;
}

function projectRow(project, onArchive) {
  const row = element('li');
  row.dataset.testid = 'project-row';
  const button = element('button', 'Open project');
  button.type = 'button';
  button.addEventListener('click', () => location.assign(`/projects/${project.id}`));
  const summary = element('span', `${project.completed}/${project.total} completed`);
  summary.dataset.testid = 'project-summary';
  const archive = element('button', project.archived ? 'Restore project' : 'Archive project');
  archive.type = 'button';
  archive.addEventListener('click', async () => {
    archive.disabled = true;
    try {
      const updated = await request(`/api/projects/${project.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ archived: !project.archived }),
      });
      Object.assign(project, updated);
      app.querySelector('[role="alert"]')?.remove();
      onArchive();
    } catch (error) {
      showError(error.message);
    } finally {
      archive.disabled = false;
    }
  });
  row.append(element('span', project.name), summary, button, archive);
  return row;
}


